contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        uint256 supplyBefore = c.totalSupply();
        uint256 distributedBefore = c.totalDistributed();
        uint256 remainingBefore = c.totalRemaining();
        uint256 ownerBalanceBefore = c.balanceOf(address(this));
        require(amount <= ownerBalanceBefore);

        c.burn(amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 distributedAfter = c.totalDistributed();
        uint256 remainingAfter = c.totalRemaining();
        uint256 ownerBalanceAfter = c.balanceOf(address(this));

        assert(
            supplyAfter == supplyBefore - amount &&
            distributedAfter == distributedBefore - amount &&
            remainingAfter == remainingBefore &&
            ownerBalanceAfter == ownerBalanceBefore - amount
        );
    }
}

